'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={bulb:'M9 18h6m-5 3h4 M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3',mask:'M3 7c3 0 6 2 9 2s6-2 9-2v5c0 5-4 8-9 8s-9-3-9-8z M6 12l3 1m6 0 3-1 M9 16h6',shuffle:'M3 6h3c5 0 7 12 12 12h3m-4-4 4 4-4 4 M3 18h3c2 0 3-2 4-4m4-4c1-2 2-4 4-4h3m-4-4 4 4-4 4',arrow:'M5 12h14m-5-5 5 5-5 5',back:'m14 6-6 6 6 6',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m8 0a4 4 0 0 1 0 8',cards:'m4 7 12-3 4 15-12 3z M4 17 2 3l12-1',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M6 10V7a6 6 0 0 1 12 0v3 M4 10h16v12H4z M12 15v3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',chat:'M3 3h18v14H9l-6 5z M7 8h10 M7 12h6',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M18 6 6 18',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',cup:'M7 3h10v7a5 5 0 0 1-10 0z M7 5H3v4a4 4 0 0 0 4 4m10-8h4v4a4 4 0 0 1-4 4M12 15v6m-4 0h8',mail:'M3 5h18v14H3z m0 0 9 8 9-8',share:'M12 16V2m-4 4 4-4 4 4 M5 10H3v12h18V10h-2',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',heart:'M12 21 3 12C-2 5 7-1 12 6c5-7 14-1 9 6z',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.cards}"/></svg>`;
const screens=[['setup','S01','Classic home'],['players','S02','Names sheet'],['categories','S03','Category sheet'],['imposters','S04','Imposters sheet'],['timer','S22','Timer sheet'],['reveal','S05','Secret reveal'],['discussion','S06','Discussion'],['confirm','S07','Reveal confirmation'],['result','S08','Classic result'],['resume','S09','Resume game'],['help','S15','How to play sheet'],['packs','S16','Subscription status'],['detail','S17','Subscription paywall'],['purchase','S18','Purchase states'],['settings','S19','Settings'],['exit','S20','Exit confirmation'],['error','S21','Recovery'],['share','S23','Share'],['rate','S24','Enjoying the game?'],['feedback','S25','Suggestion'],['nativeReview','S26','Native rating preview'],['splash','S00','Launch']];
const free=CATALOG.filter(c=>!c.paid),paid=CATALOG.filter(c=>c.paid),titles=paid.map(c=>c.name.en);
const packNames=Object.fromEntries(paid.map((c,i)=>[c.id,titles[i]]));
const defaults=()=>({mode:'classic',players:['Player 1','Player 2','Player 3'],selected:free.map(c=>c.id),contentLang:'en',imposters:'auto',hint:false,timer:false,troll:false,minutes:3,sound:true,haptic:true,music:false,subscription:null,owned:[],history:[],previous:[],round:null});
function migrateState(parsed){
 if(!parsed||!Array.isArray(parsed.selected))throw Error('Invalid snapshot');
 const names=parsed.players||parsed.groups?.quick;
 if(!Array.isArray(names)||names.length<3||names.length>20)throw Error('Invalid group');
 const migrated={...defaults(),...parsed,mode:'classic',players:names};delete migrated.groups;delete migrated.rounds;
 if(migrated.round){if(migrated.round.mode==='guided')migrated.round=null;else{migrated.round.mode='classic';migrated.round.hint??=migrated.hint;migrated.round.trollRound??=false;}}
 migrated.selected=migrated.selected.filter(id=>CATALOG.some(c=>c.id===id&&(!c.paid||migrated.subscription?.active||migrated.owned.includes(id))));
 if(!migrated.selected.length)migrated.selected=free.map(c=>c.id);
 return migrated;
}
let state=defaults(),storageError=false;
try{const raw=localStorage.getItem('oddly-prototype-v3')||localStorage.getItem('oddly-prototype-v2')||localStorage.getItem('oddly-prototype-v1');if(raw)state=migrateState(JSON.parse(raw));}catch{storageError=true;}
let view='app',screen=state.round&&!state.round.completed?'resume':'setup',modal=null,detailId=paid[0].id,shopStatus='ready',seen=false,showing=false,helpBack='setup',purchaseState='ready',lastTick=performance.now();
const people=()=>state.players;const maxImp=()=>Math.max(1,Math.min(6,Math.floor((people().length-1)/2)));
const autoImp=()=>people().length<6?1:people().length<10?2:people().length<15?3:4;
const impCount=()=>Math.min(maxImp(),state.imposters==='auto'?autoImp():Number(state.imposters));
const save=()=>{try{localStorage.setItem('oddly-prototype-v3',JSON.stringify(state));}catch{storageError=true;toast('Could not save locally. This session can continue.');}};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
const btn=(text,action,kind='primary',disabled=false)=>`<button class="${kind}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const ib=(name,action,label)=>`<button class="icon-btn" data-action="${action}" aria-label="${label}">${icon(name)}</button>`;
const header=(title='',back='setup')=>`<div class="app-header">${title?ib('back','go:'+back,'Back'):'<span class="brand">Suslo</span>'}${title?`<strong>${title}</strong>`:''}<div class="header-actions">${!title?ib('help','help','How to play'):''}${ib(title?'close':'settings',title?'go:'+back:'go:settings',title?'Close':'Settings')}</div></div>`;
const title=(h,p='')=>`<h1>${h}</h1>${p?`<p class="sub">${p}</p>`:''}`;
const row=(i,h,p,action,tail='›')=>`<button class="row" data-action="${action}"><span class="tile-icon">${icon(i)}</span><span class="row-copy"><strong>${h}</strong><small>${p}</small></span><span class="arrow">${tail}</span></button>`;
const toggle=(key,h,p)=>`<div class="option"><div><strong class="${['hint','troll'].includes(key)?'setting-title':''}">${key==='hint'?'<span class="setting-emoji" aria-hidden="true">💡</span>':key==='troll'?'<span class="setting-emoji" aria-hidden="true">😈</span>':''}${h}</strong><small>${p}</small></div><button role="switch" aria-checked="${!!state[key]}" aria-label="${h}" class="switch ${state[key]?'on':''}" data-action="toggle:${key}"></button></div>`;
const stepper=()=>`<div class="stepper"><button data-action="count:-1" aria-label="Remove player" ${people().length<=3?'disabled':''}>−</button><strong>${people().length} players</strong><button data-action="count:1" aria-label="Add player" ${people().length>=20?'disabled':''}>+</button></div>`;
function packTitle(id){return id==='bundle'?'Game Night Collection':packNames[id]||id;}
const isSubscriber=()=>state.subscription?.active===true;
const owned=id=>isSubscriber()||(id!=='bundle'&&state.owned.includes(id));
function displayWord(w){return w.value[state.contentLang]||w.value.en;}
function startRound(){
 if(!state.selected.length){toast('Choose at least one category.');return go('categories');}
 const eligible=CATALOG.filter(c=>state.selected.includes(c.id)&&(!c.paid||owned(c.id)));if(!eligible.length){toast('Choose a free or owned category.');return go('categories');}
 const fresh=eligible.filter(c=>c.words.some(w=>!state.history.includes(w.id)));const cats=fresh.length?fresh:eligible;const c=cats[Math.floor(Math.random()*cats.length)];let words=c.words.filter(w=>!state.history.includes(w.id));if(!words.length)words=c.words.filter(w=>w.id!==state.round?.word.id);if(!words.length)words=c.words;
 const word=words[Math.floor(Math.random()*words.length)],pool=people().map((_,i)=>({i,w:state.previous.includes(i)?.5:1})),imposters=[];
 for(let k=0;k<impCount();k++){let x=Math.random()*pool.reduce((a,b)=>a+b.w,0),j=0;while(j<pool.length-1&&(x-=pool[j].w)>0)j++;imposters.push(pool.splice(j,1)[0].i);}
 const trollRound=state.troll&&Math.random()<0.15;
 const roles=trollRound?people().map((_,i)=>i):imposters;
 state.round={id:Date.now(),mode:'classic',players:[...people()],word,category:c.name[state.contentLang]||c.name.en,lang:state.contentLang,imposters:roles,hint:state.hint,trollRound,starter:Math.floor(Math.random()*people().length),index:0,phase:'reveal',remaining:state.timer?state.minutes*60:null,paused:true,completed:false};
 state.history=[...state.history,word.id].slice(-500);if(!trollRound)state.previous=imposters;seen=false;showing=false;save();go('reveal');
}
function go(s){if(s==='help'){hideSecret();modal='help';return render();}if(s==='categories'){categoryDraft=[...state.selected];modal='categories';return render();}hideSecret();screen=s;modal=null;if(state.round&&['reveal','discussion','result'].includes(s)){state.round.phase=s;save();}render();}
function sample(s){state.round=null;modal=null;
 if(['reveal','discussion','confirm','result','resume','exit'].includes(s)){startRound();if(s==='result')state.round.completed=true;}
 if(s==='confirm'){screen='discussion';modal='reveal';}else if(s==='exit'){screen='discussion';modal='exit';}else if(s==='purchase'){screen='detail';modal='purchase';purchaseState='ready';}else if(['help','categories','players','imposters','timer','share','rate','feedback','nativeReview'].includes(s)){screen='setup';modal=s;if(s==='categories')categoryDraft=[...state.selected];if(s==='timer')state.timer=true;}else screen=s;
 if(state.round&&['reveal','discussion','result'].includes(screen))state.round.phase=screen;save();render();}
function categorySummary(){const selected=CATALOG.filter(c=>state.selected.includes(c.id));const all=selected.length===CATALOG.length;return `<button class="row category-summary" data-action="sheet:categories"><span class="row-copy"><strong class="setting-title"><span class="setting-emoji" aria-hidden="true">🗂️</span>Categories</strong><span class="selected-category-tags">${all?'<span class="selected-category-tag">All</span>':selected.length?selected.map(c=>`<span class="selected-category-tag"><span aria-hidden="true">${c.emoji}</span> ${esc(c.name[state.contentLang]||c.name.en)}</span>`).join(''):'<span class="selected-category-tag">Select categories</span>'}</span></span><span class="arrow" aria-hidden="true">›</span></button>`;}
function setup(){return header()+`<div class="home-heading"><h1>Who’s bluffing?</h1><p class="sub">One phone. Your whole crew.</p><img class="suslo-hero" src="assets/suslo-cards.png" width="320" height="140" alt="" aria-hidden="true"><span class="pill">CLASSIC · 3–20 PLAYERS</span></div><div class="card crew-card"><div class="card-top"><h3 class="setting-title"><span class="setting-emoji" aria-hidden="true">👥</span>Your crew</h3><button class="text-btn" data-action="sheet:players">Edit names</button></div>${stepper()}</div><div class="card list-card">${categorySummary()}</div><div class="card home-options"><div class="option"><div><strong class="setting-title"><span class="setting-emoji" aria-hidden="true">🥷</span>Imposters</strong><small>Auto recommends ${autoImp()} for your crew.</small></div><button class="value-button" data-action="sheet:imposters">${state.imposters==='auto'?'Auto · ':''}${impCount()} <span>⌄</span></button></div>${toggle('hint','Imposter hint','Show the category, never the word.')}<div class="option timer-option"><button class="timer-copy" data-action="timerSheet" ${!state.timer?'disabled':''}><strong class="setting-title"><span class="setting-emoji" aria-hidden="true">⏱️</span>Discussion timer</strong><small>${state.timer?`${state.minutes} minute${state.minutes===1?'':'s'} · Tap to change duration`:'Off · Play at your own pace.'}</small></button><button role="switch" aria-checked="${state.timer}" aria-label="Discussion timer" class="switch ${state.timer?'on':''}" data-action="toggle:timer"></button></div>${toggle('troll','Troll mode','Some rounds, everyone is an impostor.')}</div><div class="home-support"><span class="eyebrow">GOOD TIMES ARE BETTER SHARED</span><div class="support-buttons">${btn(icon('share')+' Share','sheet:share','secondary')}${btn(icon('star')+' Rate us','sheet:rate','secondary')}</div><p class="footnote">Unlimited free rounds. No account needed.</p></div>`;}
function homeDock(){return `<div class="home-dock" ${modal?'inert':''}>${!owned('bundle')?btn(icon('cup')+' Premium','premium','premium-button'):''}${btn('Start game '+icon('arrow'),'start','primary',!state.selected.length)}</div>`;}
function players(){return `<h2>Your crew</h2><p>Names are optional. Your group is saved for next time.</p>${stepper()}<div class="name-fields">${people().map((n,i)=>`<label class="field"><span class="avatar">${i+1}</span><input aria-label="Player ${i+1} name" data-name="${i}" value="${esc(n)}" maxlength="28" placeholder="Player ${i+1}"></label>`).join('')}</div>${btn('Save names','closeModal')}`;}
function reveal(){const r=state.round;if(!r)return setup();return header('Secret roles','resume')+`<div class="center"><span class="pill">PLAYER ${r.index+1} OF ${r.players.length}</span><h1 style="margin-top:17px">${esc(r.players[r.index])}</h1><p class="sub">Make sure only you can see the screen.</p></div><div class="progress"><span style="width:${r.index/r.players.length*100}%"></span></div><button class="secret-card" id="hold-card" aria-label="Hold to reveal your private role. Release to hide.">${secretFace(false)}</button><p class="footnote" id="pass-message">Hold the card to peek. Release to hide.</p><div class="actions">${btn((r.index===r.players.length-1?'Let’s play':'Next player')+' '+icon('arrow'),'nextPlayer','primary',!seen)}<button class="link-center" data-action="accessibleReveal">Reveal / hide without holding</button></div>`;}
function secretFace(visible){const r=state.round;if(!visible)return `${icon('lock')}<h2>For your eyes only.</h2><p>Hold to reveal</p><span class="pill" style="margin-top:20px">RELEASE TO HIDE</span>`;const imp=r.imposters.includes(r.index);return `${icon('eye')}<span class="pill" style="margin-top:16px">${imp?'YOUR ROLE':'THE SECRET WORD'}</span><h2>${imp?'You’re an impostor.':esc(r.word.value[r.lang]||r.word.value.en)}</h2><p>${imp?(r.hint?'Hint: '+esc(r.category):'Listen closely. Bluff your way in.'):esc(r.category)}</p><p>Keep it to yourself.</p>`;}
function showSecret(){if(screen!=='reveal'||!state.round)return;showing=true;seen=true;const el=$('#hold-card');if(el){el.innerHTML=secretFace(true);el.setAttribute('aria-label','Private role revealed. Release to hide.');}const next=$('[data-action="nextPlayer"]');if(next)next.disabled=true;}
function hideSecret(){if(!showing)return;showing=false;const el=$('#hold-card');if(el){el.innerHTML=secretFace(false);el.setAttribute('aria-label','Hold to reveal your private role. Release to hide.');}const next=$('[data-action="nextPlayer"]');if(next)next.disabled=!seen;if($('#pass-message'))$('#pass-message').textContent='Hidden. You can pass the phone now.';}
function discussion(){const r=state.round;return header('Classic round','resume')+`<div class="bubble-art"><span>•••</span><span>?</span></div><div class="center">${title('Let the bluffing begin.','Give clues. Get suspicious. Vote together.')}<span class="pill">STARTS THE CONVERSATION</span><p class="starter">${esc(r.players[r.starter])}</p></div>${r.remaining!==null?`<div class="card center"><div class="big-number" id="timer">${time(r.remaining)}</div><button class="text-btn" data-action="pause" id="pause-label">${r.paused?'Resume timer':'Pause timer'}</button></div>`:'<div class="callout center">No rush. Keep the conversation off-screen.<br>Ready? Point to who you think is bluffing.</div>'}<div class="actions">${btn('Reveal imposters & word','confirmReveal')}<button class="link-center" data-action="exit">End this round</button></div>`;}
function result(){const r=state.round;return header('The reveal','setup')+`<div class="center"><div class="hero-symbol">${icon('eye')}</div><span class="pill">${r.trollRound?'TROLL ROUND':'THE IMPOSTER'+(r.imposters.length>1?'S':'')}</span><h1 style="margin-top:15px">${r.trollRound?'Plot twist. Everyone!':'The secret is out.'}</h1><div class="chips" style="justify-content:center">${r.imposters.map(i=>`<span>${esc(r.players[i])}</span>`).join('')}</div></div><div class="card center"><span class="eyebrow">THE SECRET WORD</span><h2 style="font-size:32px;margin:13px 0">${esc(r.word.value[r.lang]||r.word.value.en)}</h2><span class="pill">${esc(r.category)}</span></div><p class="sub center">${r.trollRound?'Nobody knew. Everybody bluffed.':'Who had the best poker face?'}</p><div class="actions">${btn('Play again '+icon('refresh'),'start')}${btn('Edit game','editGame','secondary')}${!isSubscriber()?btn('Try 20 more categories','paywall:round_result','text-btn'):''}</div>`;}
function resume(){return header('Your game','setup')+`<div class="hero-symbol">${icon('lock')}</div><div class="center">${title('Your crew can wait.','Your round is saved. All roles stay hidden until you’re ready.')}</div><div class="card center"><h3>${state.round?.players.length||people().length} players · Classic</h3><p class="sub" style="margin:10px 0 0">Pick up right where you left off.</p></div><div class="actions">${btn('Resume game','resume','primary',!state.round)}${btn('End & start fresh','exit','secondary')}</div>`;}
function help(){return `<h2 id="help-title">How to play</h2><ol class="help-steps">${[
'Gather 3–20 players and pass one phone around.',
'Hold to see your secret, then release to hide it. Most players get the same word. Impostors only see their role.',
'The app picks who starts. Take turns giving a short clue related to the secret word.',
'If you’re an impostor, listen and bluff. Blend in without knowing the word.',
'Keep sharing clues and discussing. When you’re ready, vote together away from the phone.',
'Tap Reveal and confirm to show the word and all impostors. Play again starts a fresh round with the same group.'
].map((text,i)=>`<li><span class="help-number" aria-hidden="true">${i+1}</span><p>${text}</p></li>`).join('')}</ol><p class="help-note"><strong>A little twist?</strong> Optional hints show impostors the category. With Troll mode on, some rounds make everyone an impostor — revealed only at the end.</p>`;}

function packs(){return header('Premium')+title(isSubscriber()?'You’re Premium.':'More ways to bluff.',isSubscriber()?'All 20 premium categories are available.':'Three free categories. Twenty more with Premium.')+`<div class="card"><h3>${isSubscriber()?state.subscription.plan==='annual'?'Annual subscription':'Weekly subscription':'Play free, whenever you want.'}</h3><p>${isSubscriber()?'Demo subscription active. Manage renewal in your Apple account in the real app.':'Unlimited Classic rounds with Food, Animals and Sports.'}</p>${isSubscriber()?btn('Manage subscription','manageSubscription','secondary'):btn('Explore Premium','paywall:settings')}</div>${btn('Restore purchases','restore','secondary')}<p class="footnote">Local demo — no real Apple subscription is changed.</p>`;}
function detail(){return paywall();}
function settings(){return header('Settings')+title('Make yourself at home.','Small preferences for a better game night.')+`<div class="card">${toggle('sound','Sound effects','The same subtle sound for every role.')}${toggle('haptic','Haptics','Gentle feedback, when supported.')}${toggle('music','Background music','Off by default. Let the conversation lead.')}<div class="option"><div><strong>Content language</strong><small>Interface preview is in English.</small></div><select aria-label="Content language" data-setting="contentLang">${[['en','English'],['pt-BR','Português'],['es','Español'],['hi','हिन्दी'],['ar','العربية']].map(([k,n])=>`<option value="${k}" ${state.contentLang===k?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="card list-card">${row('cards',isSubscriber()?'Manage Premium':'Explore Premium','Annual or weekly subscription','go:packs')}${row('refresh','Restore purchases','Restore subscription and legacy access','restore')}${row('mail','Send feedback','A suggestion or something not quite right?','feedback')}${row('lock','Privacy & terms','About this local prototype','privacy')}</div><button class="link-center" data-action="resetHistory">Clear word history</button><button class="link-center" data-action="forget">Forget saved group</button><p class="footnote">Suslo · Design prototype 3.1<br>Local demo · No data is sent</p>`;}
function errorScreen(){return header('Something went wrong')+`<div class="hero-symbol">${icon('refresh')}</div><div class="center">${title('Let’s try that again.','We couldn’t recover this round. Your group and purchases are safe.')}</div><div class="callout">This screen demonstrates a recoverable local-save error.</div><div class="actions">${btn('Try again','retry')}${btn('Back to setup','editGame','secondary')}</div>`;}
function modalContent(){if(!modal)return '';let body='';
 if(modal==='players')body=players();
 if(modal==='categories')body=categories();
 if(modal==='allCategoriesLanguage')body=`<h2>Play all categories in English?</h2><p>Premium categories are in English. Selecting all switches your content language to English.</p>${btn('Use English & select all','allCategoriesEnglish')}${btn('Cancel','closeModal','secondary')}`;
 if(modal==='help')body=help();
 if(modal==='manage')body=`<h2>Manage Premium</h2><p>In the iOS app this opens Apple subscription management. Here you can preview expiration without changing any real subscription.</p>${btn('Simulate expiration','expire','secondary')}${btn('Done','closeModal')}`;
 if(modal==='imposters')body=`<h2>How many imposters?</h2><p>Auto adapts to your ${people().length} players. Each impostor knows only their own role.</p><button class="selection-row ${state.imposters==='auto'?'chosen':''}" data-action="setImposters:auto"><span><strong>Auto · ${autoImp()}</strong><small>Recommended for your crew</small></span><span>${state.imposters==='auto'?'✓':''}</span></button><div class="chips">${Array.from({length:maxImp()},(_,i)=>`<button data-action="setImposters:${i+1}" class="${state.imposters==i+1?'selected':''}">${i+1}</button>`).join('')}</div>${btn('Done','closeModal')}`;
 if(modal==='timer')body=`<h2>A little time pressure.</h2><p>Choose a discussion time. Reaching zero never reveals the roles automatically.</p><div class="duration-grid">${Array.from({length:10},(_,i)=>`<button class="${state.minutes===i+1?'selected':''}" data-action="duration:${i+1}">${i+1}<small>min</small></button>`).join('')}</div>${btn('Use '+state.minutes+' minutes','closeModal')}`;
 if(modal==='share')body=`<span class="tile-icon">${icon('share')}</span><h2 style="margin-top:16px">Bring your whole crew.</h2><p>One phone, one secret word, and a group of very suspicious friends.</p>${btn('Share app link','shareApp')}${btn('Copy app link','copyLink','secondary')}<input class="share-url" readonly aria-label="App link" value="${APP_LINK}"><p class="footnote">Uses the existing published app link while the new brand is provisional.</p>`;
 if(modal==='rate')body=`<div class="center"><div class="hero-symbol">${icon('heart')}</div><h2>Enjoying Suslo?</h2><p>We’d love to hear how your game night is going.</p></div>${btn('Yes, love it!','sheet:nativeReview')}${btn('Not quite yet','sheet:feedback','secondary')}<button class="link-center" data-action="closeModal">Maybe later</button>`;
 if(modal==='feedback')body=`<h2>Help us make it better.</h2><p>What could make your next game night more fun?</p><label class="feedback-label" for="suggestion">Your suggestion</label><textarea id="suggestion" rows="4" maxlength="1000" placeholder="Tell us what we could improve…">${esc(suggestionDraft)}</textarea>${btn('Send suggestion','sendSuggestion')}<button class="link-center" data-action="closeModal">Not now</button><p class="footnote">Local preview: no message is sent.</p>`;
 if(modal==='feedbackSent')body=`<div class="hero-symbol">${icon('check')}</div><h2>Thanks for the suggestion.</h2><p>This preview shows the confirmation only. Your message was not sent or stored.</p>${btn('Back to game','closeModal')}`;
 if(modal==='nativeReview')body=`<div class="center native-rating"><span class="brand">Suslo</span><h2>Enjoying Suslo?</h2><p>Tap a star to rate it on the App Store.</p><div class="rating-stars" aria-label="Rating preview">${[1,2,3,4,5].map(n=>`<button data-action="rating:${n}" aria-label="${n} star${n>1?'s':''}" aria-pressed="${ratingValue===n}">${n<=ratingValue?'★':'☆'}</button>`).join('')}</div>${btn('Submit preview','submitRating','primary',!ratingValue)}<button class="link-center" data-action="closeModal">Not now</button><p class="footnote">Simulated native prompt. HTML cannot open StoreKit.</p></div>`;
 if(modal==='reveal')body=`${icon('eye')}<h2>Ready for the reveal?</h2><p>This shows the word and every impostor. Make sure everyone has voted together first.</p>${btn('Reveal everyone','doReveal')}${btn('Keep talking','closeModal','secondary')}`;
 if(modal==='exit')body=`<h2>End this round?</h2><p>This round will be cleared. Your group, preferences and purchases stay saved.</p>${btn('End round','end')}${btn('Keep playing','closeModal','secondary')}`;
 if(modal==='purchase')body=purchaseModal();
 if(modal==='language')body=`<h2>Play this category in English?</h2><p>This category is in English. We’ll switch the content language and clear your previous category selection. The interface stays the same.</p>${btn('Use English content','useEnglish')}${btn('Cancel','closeModal','secondary')}`;
 if(modal==='forget'||modal==='resetHistory')body=`<h2>${modal==='forget'?'Forget this group?':'Clear word history?'}</h2><p>${modal==='forget'?'Names return to Player 1, Player 2 and Player 3.':'Previously played words can appear again.'} Purchases are not affected.</p>${btn('Confirm','confirmReset')}${btn('Cancel','closeModal','secondary')}`;
 if(modal==='privacy')body=`<h2>Your game stays here.</h2><p>This HTML prototype saves groups, settings and demo purchases in this browser only. No analytics, accounts or payments are connected. Sharing happens only when you request it.</p>${btn('Got it','closeModal')}`;
 return `<div class="modal-backdrop ${['rate','nativeReview','feedbackSent'].includes(modal)?'centered-modal':''}"><section class="sheet ${modal==='players'?'names-sheet':modal==='categories'?'category-sheet':modal==='help'?'help-sheet':''}" role="dialog" aria-modal="true" aria-label="${modal==='help'?'How to play':modal}"><button class="sheet-close icon-btn" data-action="closeModal" aria-label="Close dialog">${icon('close')}</button>${body}</section></div>`;
}
function purchaseModal(){const info={ready:['Confirm your plan',`Demo checkout: ${selectedPlan==='annual'?'$19.99 per year':'$4.99 per week'}, auto-renewing. No free trial.`],success:['Welcome to Premium!','All 20 premium categories are unlocked while subscribed.'],cancelled:['Subscription cancelled','No demo access was added. Your free games are ready.'],pending:['Waiting for approval','Premium unlocks only after approval. You can keep playing free.'],failed:['Couldn’t subscribe','Try again, or continue with your free categories.'],restored:['Restore checked',isSubscriber()?'Your demo subscription is active.':'No active demo subscription found. Legacy purchases remain available.']};const [h,p]=info[purchaseState]||info.ready;return `<span class="pill">SIMULATED CHECKOUT</span><h2 style="margin-top:15px">${h}</h2><p>${p}</p>${purchaseState==='ready'?`<div class="chips">${['success','cancelled','pending','failed'].map(x=>btn(x,'purchaseOutcome:'+x,'secondary')).join('')}</div>${btn('Cancel','closeModal','secondary')}`:btn('Continue',purchaseState==='success'?'finishSubscribe':'closeModal')}`;}
function appScreen(){switch(screen){case'setup':return setup();case'categories':return categories();case'reveal':return reveal();case'discussion':return state.round?discussion():setup();case'result':return state.round?result():setup();case'resume':return resume();case'help':return help();case'packs':return packs();case'detail':return detail();case'settings':return settings();case'error':return errorScreen();case'splash':return `<div class="loading-mark"><span class="brand">Suslo</span><p class="sub">Good company. Great bluffs.</p><div class="loader"></div>${btn('Continue','go:setup','secondary')}</div>`;default:return setup();}}
let categoryDraft=[], selectedPlan='annual', paywallReturn={screen:'setup',modal:null}, pendingCategory=null, paywallPlacement='home_premium';
function openPaywall(placement){paywallReturn={screen,modal};paywallPlacement=placement;if(placement!=='locked_category')pendingCategory=null;modal=null;return go('detail');}
function closePaywall(){screen=paywallReturn.screen||'setup';modal=paywallReturn.modal;render();}
function categories(){return `<h2>Select categories</h2><p>Choose one or more for your game.</p><div class="category-bulk"><button class="text-btn" data-action="selectAllCategories">Select all${isSubscriber()?'':' free'}</button><button class="text-btn" data-action="clearCategories" ${!categoryDraft.length?'disabled':''}>Clear</button></div><div class="category-list">${CATALOG.map(c=>{const locked=c.paid&&!owned(c.id),selected=categoryDraft.includes(c.id);return `<button class="category-line ${selected&&!locked?'chosen':''}" data-action="category:${c.id}" aria-label="${esc(c.name[state.contentLang]||c.name.en)}${locked?', locked':''}" aria-pressed="${selected&&!locked}"><span class="category-emoji">${c.emoji}</span><span class="category-label">${esc(c.name[state.contentLang]||c.name.en)}${c.paid&&state.contentLang!=='en'?'<small>English content</small>':''}</span><span class="category-state">${locked?icon('lock'):selected?'✓':''}</span></button>`}).join('')}</div><div class="category-confirm">${btn('Confirm · '+categoryDraft.length+' selected','confirmCategories','primary',!categoryDraft.length)}<small>3 free · 20 Premium · Unlimited rounds</small></div>`;}
function paywall(){return `<div class="app-header"><span class="brand">Suslo</span>${ib('close','paywallBack','Close paywall')}</div><div class="premium-hero"><span class="pill">SUSLO PREMIUM</span><div class="premium-art"><span>🎬</span><span>🎵</span><span>🌎</span></div><h1>More categories.<br>More “wait, what?”</h1><p>${pendingCategory?`Unlock ${esc(CATALOG.find(c=>c.id===pendingCategory)?.name.en||'this category')} and 19 more categories.`:'Unlock 20 extra categories for every kind of game night.'}</p></div><div class="premium-benefits"><span>✓ Both plans unlock the same 20 categories</span><span>✓ Choose your mix · Play unlimited rounds</span><span>✓ Premium content in English</span></div><div class="subscription-plans">${[['annual','Annual','$19.99','per year','Best yearly value'],['weekly','Weekly','$4.99','per week','Flexible weekly billing']].map(([id,name,price,period,note])=>`<button class="plan ${selectedPlan===id?'chosen':''}" data-action="plan:${id}" aria-pressed="${selectedPlan===id}"><span><strong>${name}</strong><small>${note}</small></span><span class="plan-price"><strong>${price}</strong><small>${period}</small></span><span>${selectedPlan===id?'●':'○'}</span></button>`).join('')}</div>${shopStatus==='offline'?'<div class="callout">Store unavailable. Please try again later.</div>':''}${btn('Subscribe '+(selectedPlan==='annual'?'annually':'weekly'),'purchase','primary',shopStatus==='offline')}<p class="renewal">${selectedPlan==='annual'?'$19.99 billed each year':'$4.99 billed each week'}. Auto-renews until canceled. No free trial. Manage or cancel in your Apple account.</p><button class="link-center" data-action="paywallBack">Continue with free categories</button><div class="paywall-links"><button data-action="privacy">Terms</button><button data-action="privacy">Privacy</button><button data-action="restore">Restore</button></div><p class="footnote">Illustrative prices · Local demo · No charge</p>`;}
let categoryScroll=0,renderedScreen=null,scrollMemory={},suggestionDraft='',ratingValue=0;
function render(){if($('.category-list'))categoryScroll=$('.category-list').scrollTop||0;if(renderedScreen&&$('#app'))scrollMemory[renderedScreen]=$('#app').scrollTop||0;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view!=='app'){$('#workspace').innerHTML=view==='system'?designSystem():flowBoard();return;}
 const reviewScreen=modal==='reveal'?'confirm':modal==='purchase'?'purchase':modal==='exit'?'exit':modal&&screens.some(x=>x[0]===modal)?modal:screen; const s=screens.find(x=>x[0]===reviewScreen)||screens[0];$('#workspace').innerHTML=`<div class="workspace-app"><aside class="rail left-rail"><p class="eyebrow">THE EXPERIENCE</p><h2>Less setup.<br>More good company.</h2><p>Coral warmth meets a clear, compact layout. Explore the game or jump to any screen.</p><nav class="screen-nav" aria-label="Screen gallery">${screens.map(([k,id,n])=>`<button data-sample="${k}" class="${k===reviewScreen?'active':''}"><span>${id}</span>${n}</button>`).join('')}</nav></aside><main class="device-stage"><div class="device"><div class="status"><span>9:41</span><span>▮▮▮ ◔ ▰</span></div><div class="app ${screen==='setup'?'home-scroll':screen==='detail'?'paywall-scroll':''} ${screen==='setup'&&owned('bundle')?'is-premium':''}" id="app" ${modal?'inert':''}>${appScreen()}</div>${screen==='setup'?homeDock():''}${modalContent()}</div><span class="screen-label">${s[1]} / ${s[2]} · Interactive prototype</span><div class="stage-tools"><button data-action="interrupt">Simulate interruption</button><button data-action="storeStatus">Store: ${shopStatus}</button><button data-action="resetDemo">Reset demo</button></div></main><aside class="rail right-rail"><p class="eyebrow">DESIGN INTENT</p><div class="note-card"><h3>Warm, not busy.</h3><p>Ivory surfaces, coral actions and small sunny details. The game is the conversation.</p></div><div class="note-card"><h3>One clear next step.</h3><p>Start with defaults. All game options live on the home screen. Names, imposters and duration open in bottom sheets.</p></div><div class="note-card"><h3>Try the full flow</h3><p>Start a game, hold each card, release and pass. Talk and vote together, then reveal everyone. Classic is the only mode.</p></div><div class="note-card"><h3>Prototype boundaries</h3><p>Real local interactions and saved rounds. Simulated payments. English UI; three translated free categories and English premium samples. No real analytics or emails. StoreKit rating is a visual simulation.</p></div><p>Screen shortcuts create sample rounds. They are for design review, not in-game navigation.</p></aside></div>`;
 const hold=$('#hold-card');if(hold){hold.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();hold.setPointerCapture(e.pointerId);showSecret();});hold.addEventListener('pointerup',hideSecret);hold.addEventListener('pointercancel',hideSecret);hold.addEventListener('lostpointercapture',hideSecret);hold.addEventListener('pointermove',e=>{const b=hold.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)hideSecret();});hold.addEventListener('contextmenu',e=>e.preventDefault());hold.addEventListener('keydown',e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)showSecret();}});hold.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key))hideSecret();});hold.addEventListener('blur',hideSecret);}
 if($('#app'))$('#app').scrollTop=scrollMemory[screen]||0;renderedScreen=screen;
 if($('.category-list'))$('.category-list').scrollTop=categoryScroll;
 if(modal)requestAnimationFrame(()=>$('.sheet button')?.focus({preventScroll:true}));
}
function designSystem(){return `<main class="board"><p class="eyebrow">SUSLO / DESIGN SYSTEM 3.1</p><h1>Good company, by design.</h1><p class="sub">Coral Social, evolved for Suslo. Expressive cards, warm ivory and clear coral actions for the moments between friends.</p><div class="board-grid">${[['Coral / Action','#c84232','White labels · primary action'],['Ivory / Canvas','#fff9f3','Warm, calm foundation'],['Ink / Content','#38221d','Headlines and body'],['Peach / Supporting','#fae8dd','Controls and quiet highlights'],['Gold / Personality','#f7c862','Small moments of warmth'],['Sage / Success','#346c53','Ownership and confirmation']].map(([n,c,d])=>`<section class="card"><div class="swatch" style="background:${c}"></div><h3>${n}</h3><p>${c.toUpperCase()}<br>${d}</p></section>`).join('')}</div><div class="board-grid" style="grid-template-columns:1fr 1fr"><section class="card"><p class="eyebrow">TYPOGRAPHY</p><h1 style="font-size:36px">Who’s bluffing?</h1><p>Rubik 650 · 31/36 · Headlines</p><h3>Your whole crew.</h3><p>Plus Jakarta Sans · 12/19 body, 13/18 buttons<br>Both fonts bundled locally. No network requests.</p><span class="pill">LABELS · 9–10 PX IN PROTOTYPE</span><p>Production: scale supporting labels up where needed; respect system text size. No text baked into images.</p></section><section class="card"><p class="eyebrow">GEOMETRY</p><table class="token-table"><tr><td>Spacing</td><td>4 · 8 · 12 · 16 · 24 · 32</td></tr><tr><td>Screen gutter</td><td>22 px</td></tr><tr><td>Card radius</td><td>22 px</td></tr><tr><td>Button radius / height</td><td>17 px / 52 px</td></tr><tr><td>Touch target in production</td><td>44 × 44 minimum</td></tr><tr><td>Surface border</td><td>1 px · #EADBD2</td></tr></table></section><section class="card"><p class="eyebrow">ACTIONS & STATES</p>${btn('Start game '+icon('arrow'),'previewToast')}${btn('Edit game','previewToast','secondary')}${btn('Unavailable','previewToast','primary',true)}<p>One primary action. Secondary actions keep the visual volume low. Disabled controls explain their reason in context.</p></section><section class="card"><p class="eyebrow">FORM LANGUAGE</p><label class="field"><input placeholder="Player name (optional)" aria-label="Example player name"></label><span class="pill">CLASSIC · ONE MODE</span><div class="option"><strong>Optional hint</strong><button class="switch on" data-action="previewSwitch" role="switch" aria-checked="true" aria-label="Example switch"></button></div><p>Defaults let the group start immediately. Names, hints and timers stay optional.</p></section></div><section class="card"><h2>Home controls & floating actions</h2><p>Imposters: value button opens a sheet. Hint and Troll mode: switches only. Timer: switch enables it; tap the enabled row to choose a duration. Edit names: scrollable sheet. Premium and Start game float over a fully transparent dock. The home has bottom padding so Share, Rate us and the last content scroll above the buttons. Premium disappears when all three current packs are owned; no future-pack entitlement is implied.</p></section><section class="card"><h2>Icons with a light touch.</h2><div class="chips">${Object.keys(paths).map(n=>`<span>${icon(n)} ${n}</span>`).join('')}</div><p>Consistent 24 px viewBox, 1.8 px stroke. Icons support labels; they never replace the meaning of a destructive or purchase action.</p></section><section class="card"><h2>Privacy is part of the visual system.</h2><p>One shared card treatment for all roles. No role-specific sound, outer color, motion or haptic. Hide on release, blur and interruption. No secret in a preview, URL, toast or telemetry. Native screenshot protection is not simulated by this browser prototype.</p></section><section class="card"><h2>Motion & accessibility</h2><p>Small state changes, 120–200 ms; honor reduced motion. Keyboard focus uses a blue 3 px ring. Holding a card has an explicit accessible alternative. Dialogs trap focus and close with Escape. Production handoff must validate VoiceOver, Dynamic Type, RTL, 200% text and platform targets on real devices.</p></section><p class="sub">Source of truth: styles.css tokens and the PRD. This prototype validates the visual direction and flow; it is not a replacement for native accessibility or billing tests.</p></main>`;}
function flowBoard(){const flows=[['Classic / the only mode','Set up at home, then every required screen is part of the game.',[['setup','S01','Home'],['reveal','S05','Hold & pass'],['discussion','S06','Talk & vote'],['confirm','S07','Confirm'],['result','S08','Reveal & replay']]],['Home / contextual sheets','Everything returns to the same home and scroll position.',[['players','S02','Edit names'],['imposters','S04','Imposters'],['timer','S22','Timer duration'],['categories','S03','Category sheet']]],['Premium / optional content','Annual or weekly. Three free categories remain unlimited.',[['packs','S16','Subscription'],['detail','S17','Paywall'],['purchase','S18','Purchase state']]],['Support / share & feedback','Requested review routing is a design simulation; see the PRD release-policy note.',[['share','S23','Share app'],['rate','S24','Enjoying it?'],['feedback','S25','No → suggestion'],['nativeReview','S26','Yes → rating']]],['Recovery & help','Resume with roles hidden, or start fresh.',[['resume','S09','Resume'],['exit','S20','End round'],['error','S21','Recovery'],['help','S15','Rules'],['settings','S19','Settings']]]];return `<main class="board"><p class="eyebrow">NAVIGATION & BEHAVIOR / V2</p><h1>One home. One Classic game.</h1><p class="sub">All setup controls at your fingertips. Click a node to inspect its screen or bottom sheet.</p>${flows.map(([h,p,nodes])=>`<section class="card"><h2>${h}</h2><p>${p}</p><div class="flow-line">${nodes.map(([s,id,n])=>`<button class="flow-node" data-sample="${s}"><span>${id}</span><strong>${n}</strong></button>`).join('')}</div></section>`).join('')}<section class="card"><h2>Behavior notes</h2><p>Timer off → no duration sheet. Timer on → tap the row to edit time.<br>Troll mode off → normal weighted draw. On → proposed 15% chance of an all-impostor round, disclosed only at the final reveal.<br>Premium → annual or weekly subscription, with the same 20 extra categories.<br>Rating and suggestion screens never send real reviews or feedback from this prototype.</p></section></main>`;}
const APP_LINK='https://apps.apple.com/us/app/imposter-spy-out-of-the-loop/id6771190067';
async function shareApp(copyOnly=false){try{if(!copyOnly&&navigator.share){await navigator.share({title:'Suslo: Imposter Party Game',text:'One phone. Your whole crew. Let’s play!',url:APP_LINK});return;}if(navigator.clipboard){await navigator.clipboard.writeText(APP_LINK);toast('App link copied.');}else{toast('Copy the app link shown below.');modal='share';render();}}catch(e){if(e.name!=='AbortError')toast('Sharing unavailable. Try Copy app link.');}}
function act(a){const [op,arg]=a.split(':');
 if(op==='go'){if(arg==='categories'){modal='categories';categoryDraft=[...state.selected];return render();}return go(arg);}
 if(op==='sheet'){hideSecret();modal=arg;if(arg==='categories')categoryDraft=[...state.selected];if(arg==='nativeReview')ratingValue=0;return render();}
 if(op==='help'){hideSecret();modal='help';return render();}
 if(op==='count'){const g=people(),n=g.length+Number(arg);if(n<3||n>20)return;if(Number(arg)>0)g.push('Player '+n);else g.pop();if(state.imposters!=='auto'&&state.imposters>maxImp()){state.imposters=maxImp();toast('Imposter count adjusted to fit the group.');}save();return render();}
 if(op==='toggle'){state[arg]=!state[arg];save();return render();}
 if(op==='timerSheet'){if(state.timer){modal='timer';render();}return;}
 if(op==='setImposters'){state.imposters=arg==='auto'?'auto':Number(arg);save();return render();}
 if(op==='duration'){state.minutes=Number(arg);save();return render();}
 if(op==='premium')return openPaywall('home_premium');
 if(op==='paywall')return openPaywall(arg);
 if(op==='plan'){selectedPlan=arg;return render();}
 if(op==='paywallBack')return closePaywall();
 if(op==='manageSubscription'){modal='manage';return render();}
 if(op==='expire'){state.subscription=null;state.selected=state.selected.filter(id=>!paid.some(c=>c.id===id)||state.owned.includes(id));if(!state.selected.length)state.selected=free.map(c=>c.id);save();modal=null;render();return toast('Premium expired. Available categories are ready for your next round.');}
 if(op==='selectAllCategories'){if(isSubscriber()&&state.contentLang!=='en'){modal='allCategoriesLanguage';return render();}categoryDraft=(isSubscriber()?CATALOG:free).map(c=>c.id);return render();}
 if(op==='clearCategories'){categoryDraft=[];return render();}
 if(op==='allCategoriesEnglish'){state.contentLang='en';categoryDraft=CATALOG.map(c=>c.id);save();modal='categories';return render();}
 if(op==='confirmCategories'){if(!categoryDraft.length)return;state.selected=[...categoryDraft];save();modal=null;return render();}
 if(op==='finishSubscribe'){modal=null;closePaywall();if(pendingCategory){const id=pendingCategory;pendingCategory=null;return act('category:'+id);}return;} 
 if(op==='freeMix'){state.selected=free.map(c=>c.id);save();return render();}
 if(op==='category'){const c=CATALOG.find(c=>c.id===arg);if(!c)return;if(c.paid&&!owned(arg)){pendingCategory=arg;return openPaywall('locked_category');}if(c.paid&&state.contentLang!=='en'){detailId=arg;modal='language';return render();}categoryDraft=categoryDraft.includes(arg)?categoryDraft.filter(x=>x!==arg):[...categoryDraft,arg];return render();}
 if(op==='useEnglish'){state.contentLang='en';categoryDraft=[detailId];modal='categories';save();return render();}
 if(op==='start')return startRound();
 if(op==='nextPlayer'){if(!seen||showing)return;seen=false;const r=state.round;if(r.index<r.players.length-1){r.index++;save();return render();}r.paused=false;lastTick=performance.now();return go('discussion');}
 if(op==='accessibleReveal'){if(showing)hideSecret();else showSecret();return;}
 if(op==='pause'){state.round.paused=!state.round.paused;lastTick=performance.now();save();return render();}
 if(op==='confirmReveal'){modal='reveal';return render();}
 if(op==='doReveal'){state.round.completed=true;return go('result');}
 if(op==='exit'){modal='exit';return render();}
 if(op==='end'||op==='editGame'){state.round=null;save();return go('setup');}
 if(op==='resume'){if(!state.round)return;seen=false;return go(state.round.phase==='resume'?'reveal':state.round.phase);}
 if(op==='pack'){detailId=arg;return go('detail');}
 if(op==='purchase'){purchaseState='ready';modal='purchase';return render();}
 if(op==='purchaseOutcome'){purchaseState=arg;if(arg==='success'){state.subscription={active:true,plan:selectedPlan};save();}return render();}
 if(op==='restore'){purchaseState='restored';modal='purchase';return render();}
 if(op==='closeModal'){modal=['language','allCategoriesLanguage'].includes(modal)?'categories':null;render();return;}
 if(['privacy','feedback','forget','resetHistory'].includes(op)){modal=op;return render();}
 if(op==='confirmReset'){if(modal==='forget'){state.players=defaults().players;state.round=null;}else state.history=[];save();modal=null;return render();}
 if(op==='shareApp')return shareApp();if(op==='copyLink')return shareApp(true);
 if(op==='sendSuggestion'){suggestionDraft=$('#suggestion')?.value?.trim()||suggestionDraft.trim();if(!suggestionDraft){toast('Write a suggestion first.');return;}suggestionDraft='';modal='feedbackSent';return render();}
 if(op==='rating'){ratingValue=Number(arg);return render();}
 if(op==='submitRating'){modal=null;render();return toast('Preview complete. No rating was submitted.');}
 if(op==='interrupt'){if(!state.round)return toast('Start a round first.');hideSecret();state.round.paused=true;save();return go('resume');}
 if(op==='storeStatus'){shopStatus=shopStatus==='ready'?'offline':'ready';return render();}
 if(op==='resetDemo'){state=defaults();save();screen='setup';modal=null;scrollMemory={};renderedScreen=null;selectedPlan='annual';pendingCategory=null;categoryScroll=0;return render();}
 if(op==='retry'){state.round=null;save();return go('setup');}
 if(op==='previewToast')return toast('Component example — see Prototype for the game.');
}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){hideSecret();view=v.dataset.view;if(state.round)state.round.paused=true;save();render();return;}const s=e.target.closest('[data-sample]');if(s){view='app';sample(s.dataset.sample);return;}const b=e.target.closest('[data-action]');if(b){if(b.dataset.action==='previewSwitch'){b.classList.toggle('on');b.setAttribute('aria-checked',b.classList.contains('on'));return;}act(b.dataset.action);}});
document.addEventListener('input',e=>{if(e.target.id==='suggestion')suggestionDraft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.dataset.setting){const k=e.target.dataset.setting;state[k]=['minutes'].includes(k)?Number(e.target.value):e.target.value;if(k==='contentLang')state.selected=free.map(c=>c.id);save();render();}if(e.target.dataset.name!==undefined){let n=e.target.value.trim()||'Player '+(Number(e.target.dataset.name)+1);const i=Number(e.target.dataset.name);if(people().some((x,j)=>j!==i&&x.toLowerCase()===n.toLowerCase())){n+=' '+(i+1);toast('Added a number to keep names distinct.');}people()[i]=n;e.target.value=n;save();}});
document.addEventListener('keydown',e=>{if(modal&&e.key==='Escape'){e.preventDefault();modal=null;render();return;}if(modal&&e.key==='Tab'){const items=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input,.sheet select,.sheet textarea')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function pauseHidden(){hideSecret();if(state.round){state.round.paused=true;save();}if(screen==='discussion')render();}
window.addEventListener('blur',pauseHidden);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseHidden();});window.addEventListener('pagehide',pauseHidden);
function time(n){return Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');}
setInterval(()=>{const r=state.round,now=performance.now();if(r&&screen==='discussion'&&!r.paused&&r.remaining!==null&&r.remaining>0&&!document.hidden){const elapsed=(now-lastTick)/1000;r.remaining=Math.max(0,r.remaining-elapsed);if($('#timer'))$('#timer').textContent=r.remaining===0?'Time’s up':time(r.remaining);if(r.remaining===0){r.paused=true;toast('Time’s up — vote together.');if(state.haptic&&navigator.vibrate)navigator.vibrate(50);}save();}lastTick=now;},1000);
if(storageError){screen='error';}render();
